android.extraProguardRules:
# Nitro modules (VisionCamera, face detector, nitro-image): JNI-bound hybrid objects.
-keep class com.margelo.nitro.** { *; }
-keep class com.madebyevan.thumbhash.** { *; }
# ONNX Runtime: the native library looks up Java classes and fields via JNI.
-keep class ai.onnxruntime.** { *; }
# MapLibre (native SDK calls back into Java via JNI) and react-native-maps.
-keep class org.maplibre.** { *; }
-keep class com.rnmaps.** { *; }
# Reanimated / Worklets.
-keep class com.swmansion.reanimated.** { *; }
-keep class com.swmansion.worklets.** { *; }
# Expo modules: module definitions and records are read by reflection.
-keep class * extends expo.modules.kotlin.modules.Module { *; }
-keep class * implements expo.modules.kotlin.records.Record { *; }
-keep enum * implements expo.modules.kotlin.types.Enumerable { *; }
-keepclassmembers class * { @expo.modules.kotlin.records.Field *; }
# Google ML Kit (barcode + face detection).
-keep class com.google.mlkit.** { *; }
-dontwarn com.google.mlkit.**
